mapper.select:
select from edu_campus c left join sys_user u on u.id = c.principal_user_id
and ( c.campus_name like concat('%', #{keyword}, '%') or c.address like concat('%', #{keyword}, '%') or ifnull(u.real_name, '') like concat('%', #{keyword}, '%') or ifnull(u.nickname, '') like concat('%', #{keyword}, '%') or ifnull(u.username, '') like concat('%', #{keyword}, '%') )
and c.status = #{status}
and c.principal_user_id = #{principalUserId}
order by c.id desc
